def mergeLetters(s):
    stack = []
    for ch in s:
        c = ord(ch) - 97
        while c is not None and stack and stack[-1] == c:
            stack.pop()
            c = c + 1 if c < 25 else None
        if c is not None:
            stack.append(c)
    return "".join(chr(97 + c) for c in stack)
